package dev.zomboidmelee.boxing;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.model.geom.ModelPart;
/** The knee stays at the right edge. The flat heel travels down rather than toward the lens. */
public final class Foot24{
 public record Point(double x,double y,double z){}
 public record Rig(Point hip,Point knee,Point ankle,double pitch,double yaw){}
 public static Rig rig(double phase,double reach,double height,double side,double eye){double lift=StompMotion21.lift(phase),plant=StompMotion21.stamp(phase);reach=Math.max(.40,Math.min(.64,reach*.68));height=Math.max(0,Math.min(.45,height));double enter=Motion20.smooth(Math.min(phase/.12,(1-phase)/.18));Point hip=new Point(.62,-eye+.95,.10),knee=new Point(.46+.04*lift,-eye+.62+.42*lift,-.12-.12*lift);Point ankle=new Point(.29+(.13+side*.15-.29)*enter,-eye+height+3.7/16d+.32*lift,-.08+(-reach+.08)*enter);return new Rig(hip,knee,ankle,-6*lift,7*(1-plant));}
 static void segment(PoseStack p,ModelPart part,Object consumer,int light,Point a,Point b,double nativeLength){double dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z,len=Math.sqrt(dx*dx+dy*dy+dz*dz);if(len<.001)return;p.pushPose();try{p.translate(a.x,a.y,a.z);p.scale(1,-1,-1);p.mulPose(Axis.YP.rotationDegrees((float)Math.toDegrees(Math.atan2(dx,-dz))));p.mulPose(Axis.XP.rotationDegrees((float)Math.toDegrees(Math.acos(Math.max(-1,Math.min(1,-dy/len))))));p.scale(1,(float)(len/nativeLength),1);StompMesh21.drawPart(part,p,consumer,light);}finally{p.popPose();}}
 public static void draw(Object renderer,Object stack,Object buffers,int light,Object player,double phase){Client20.State s=Client20.state(player);double eye=R.num(R.call(player,"getEyeHeight")),pitch=Client20.now()-s.viewAt<100_000_000L?s.viewPitch:R.num(R.call(player,"getXRot"));Rig f=rig(phase,s.reach,s.height,s.side,eye);PoseStack p=(PoseStack)stack;Object skin=StompMesh21.consumer(buffers,R.call(R.call(player,"getSkin"),"texture"));boolean boots=!R.yes(R.call(R.call(player,"getItemBySlot",R.get(R.type("net.minecraft.world.entity.EquipmentSlot"),"FEET")),"isEmpty"));p.pushPose();try{p.mulPose(Axis.XP.rotationDegrees((float)pitch));segment(p,StompMesh21.THIGH,skin,light,f.hip,f.knee,7/16d);segment(p,StompMesh21.PANTS_THIGH,skin,light,f.hip,f.knee,7/16d);segment(p,StompMesh21.SHIN,skin,light,f.knee,f.ankle,5/16d);segment(p,StompMesh21.PANTS_SHIN,skin,light,f.knee,f.ankle,5/16d);p.pushPose();try{p.translate(f.ankle.x,f.ankle.y,f.ankle.z);p.scale(1,-1,1);p.mulPose(Axis.YP.rotationDegrees((float)f.yaw));p.mulPose(Axis.XP.rotationDegrees((float)f.pitch));if(boots){Object tex=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_global_melee","textures/entity/stomp_boot.png");StompMesh21.drawPart(StompMesh21.BOOT,p,StompMesh21.consumer(buffers,tex),light);}else StompMesh21.drawPart(StompMesh21.FOOT,p,skin,light);}finally{p.popPose();}}finally{p.popPose();}}
}
